CREATE TABLE "parent_student_links" ("institutionId" TEXT NOT NULL, "parentId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "relationship" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "parent_student_links_pkey" PRIMARY KEY ("parentId","studentId"));
CREATE TABLE "timetable_entries" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "courseOfferingId" TEXT NOT NULL, "dayOfWeek" INTEGER NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL, "room" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "timetable_entries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exams" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "courseOfferingId" TEXT NOT NULL, "title" TEXT NOT NULL, "examDate" TIMESTAMP(3) NOT NULL, "maxMarks" DOUBLE PRECISION NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "exams_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam_results" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "examId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "marks" DOUBLE PRECISION NOT NULL, "remarks" TEXT, "enteredById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "exam_results_pkey" PRIMARY KEY ("id"));
CREATE TABLE "fee_invoices" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "title" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "dueDate" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "fee_invoices_pkey" PRIMARY KEY ("id"));
CREATE TABLE "fee_payments" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "reference" TEXT, "paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "userId" TEXT, CONSTRAINT "fee_payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "notices" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "audience" TEXT NOT NULL DEFAULT 'ALL', "departmentId" TEXT, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "notices_pkey" PRIMARY KEY ("id"));
CREATE TABLE "documents" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "title" TEXT NOT NULL, "url" TEXT NOT NULL, "type" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "documents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "notifications" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_pkey" PRIMARY KEY ("id"));
